const fs = require('fs');
const executeTreasuryAction = require('./treasury');

async function runTests() {
    const results = [];
    const actions = [
        { type: 'create_wallet', userId: 'user_123', chain: 'polygon' },
        { type: 'check_balance', walletAddress: '0x1234567890abcdef1234567890abcdef12345678', chain: 'polygon' },
        { type: 'mint_receipt', email: 'test@example.com', purchaseId: 'purchase_999' },
        { type: 'unknown_action' } // to test the unknown action handler
    ];

    for (const action of actions) {
        try {
            const result = await executeTreasuryAction(action);
            results.push({ action_type: action.type, result });
        } catch (error) {
            results.push({ action_type: action.type, result: { success: false, error: error.message } });
        }
    }

    try {
        fs.writeFileSync('/home/user/treasury_test_results.json', JSON.stringify(results, null, 2));
        console.log('Tests completed and results written successfully.');
    } catch (writeError) {
        console.error('Failed to write results:', writeError);
    }
}

runTests()
    .then(() => {
        process.exit(0);
    })
    .catch((err) => {
        console.error('Test harness encountered an error:', err);
        process.exit(0); // Graceful exit as required
    });

